// Yalla Quest · Front-Office · Vue des guildes : rendu des pages et événements.
// Lit le modèle (Model/GuildeModel.js) et passe par Controller/GuildeController.js pour tout changement.
// Guild section, built on the MCD. Hash routes: #guildes #quetes #compte and #g1, #g2… for a guild's page.
(() => {
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const d = (iso, year) => new Date(iso + 'T12:00:00').toLocaleDateString('fr-FR', year ? { day: 'numeric', month: 'short', year: 'numeric' } : { day: 'numeric', month: 'short' });
  const addDays = (iso, k) => { const t = new Date(iso + 'T12:00:00'); t.setDate(t.getDate() + k); return t.toISOString().slice(0, 10); };
  const daysBetween = (a, b) => Math.round((new Date(b + 'T12:00:00') - new Date(a + 'T12:00:00')) / 864e5);
  const user = (id) => USERS.find((u) => u.id === id);
  const guild = (id) => GUILDS.find((g) => g.id === id);
  const quest = (id) => QUESTS.find((q) => q.id === id);
  const ini = (u) => user(u).pseudo.split('.').map((w) => w[0]).join('').toUpperCase();
  const who = (u) => (u === ME_ID ? 'vous' : user(u).pseudo);
  const plural = (k, one, many) => `${k} ${k > 1 ? many : one}`;
  const state = { tab: {}, guildsTab: 'all', questsTab: 'all' };
  const ART = { Force: 'force', Endurance: 'endurance', 'Mobilité': 'mobilite', Focus: 'focus', Nutrition: 'nutrition' };
  const IMG = {"force": "data:image/jpeg;base64,", "endurance": "data:image/jpeg;base64,", "mobilite": "data:image/jpeg;base64,", "focus": "data:image/jpeg;base64,", "nutrition": "data:image/jpeg;base64,"};
  const art = (type) => IMG[ART[type] || 'focus'];
  // display only (not in the MCD): each guild shows one of the five skill tiles as its emblem; new guilds take the next tile in turn
  const EMBLEMS = { g1: 'Mobilité', g2: 'Focus', g3: 'Endurance', g4: 'Nutrition', g5: 'Force' };
  const emblemOf = (g) => art(EMBLEMS[g] || Object.keys(ART)[GUILDS.findIndex((x) => x.id === g) % 5]);
  const isFull = (g) => membersOf(g).length >= MAX_MEMBERS;
  const kicker = (label) => `<p class="kicker">${new Date(TODAY + 'T12:00:00').toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' })} · ${label}</p>`;
  const foot = '<footer class="pagefoot"><img src="data:image/png;base64," alt="" width="22" height="22">Yalla Quest · « Chaque habitude est une quête. »</footer>';

  const myVote = (p) => VOTES.find((v) => v.proposal === p && v.user === ME_ID);
  const myGuilds = () => GUILDS.filter((g) => isMember(ME_ID, g.id)); // 0 or 1: a member belongs to one guild
  const myGuild = () => guild(guildOf(ME_ID));
  const iFounded = (g) => g && g.createur === ME_ID;
  const awaiting = (g) => PROPOSALS.filter((p) => p.guild === g && isOpen(p) && isMember(ME_ID, g) && !myVote(p.id));
  const openOf = (g) => PROPOSALS.filter((p) => p.guild === g && isOpen(p));
  const closesLabel = (p) => {
    const k = daysBetween(TODAY, p.date_limite_vote);
    return k === 0 ? "aujourd'hui à 23:59" : k === 1 ? 'demain à 23:59' : `le ${d(p.date_limite_vote)} (dans ${k} jours)`;
  };

  // ---------- the vote bar: pour | contre | not yet voted, over the guild's members ----------
  function tally(p) {
    const v = votesOf(p.id), pour = v.filter((x) => x.reponse_vote === 'pour').length, contre = v.length - pour;
    const total = isOpen(p) ? membersOf(p.guild).length : v.length; // a closed vote counts what was cast
    return { pour, contre, cast: v.length, missing: Math.max(total - v.length, 0), total };
  }
  function voteBar(p) {
    const t = tally(p), w = (k) => (t.total ? (k / t.total) * 100 : 0);
    return `<div class="votebar" role="img" aria-label="${t.pour} pour, ${t.contre} contre${t.missing ? `, ${t.missing} sans vote` : ''}">
        <i class="pour" style="width:${w(t.pour)}%"></i><i class="contre" style="width:${w(t.contre)}%"></i></div>
      <p class="votelegend"><span><b class="k pour"></b>${t.pour} pour</span><span><b class="k contre"></b>${t.contre} contre</span>${isOpen(p) ? `<span><b class="k none"></b>${plural(t.missing, "n'a pas voté", "n'ont pas voté")}</span>` : ''}</p>`;
  }

  // ---------- one proposition: an ivory quest card ----------
  function proposalCard(p) {
    const q = quest(p.quest), open = isOpen(p), mine = myVote(p.id), member = isMember(ME_ID, p.guild);
    const k = daysBetween(TODAY, p.date_limite_vote), urgent = open && k <= 1;
    const votes = votesOf(p.id).sort((a, b) => a.date_vote.localeCompare(b.date_vote));
    const period = q.date_debut === q.date_fin ? 'le ' + d(q.date_debut, true) : `du ${d(q.date_debut)} au ${d(q.date_fin, true)}`;
    let footer;
    if (open && member) {
      footer = `<p class="deadline${urgent ? ' urgent' : ''}">Clôture du vote <strong>${closesLabel(p)}</strong></p>
        <div class="choice" role="group" aria-label="Votre vote sur « ${esc(q.titre)} »">
          <button type="button" data-vote="${p.id}" data-answer="contre" aria-pressed="${mine?.reponse_vote === 'contre'}">Contre</button>
          <button type="button" data-vote="${p.id}" data-answer="pour" aria-pressed="${mine?.reponse_vote === 'pour'}">Pour</button>
        </div>
        ${mine ? `<p class="mine">Vous avez voté ${mine.reponse_vote} le ${d(mine.date_vote)} · modifiable jusqu'à la clôture</p>` : ''}`;
    } else if (open) {
      footer = `<p class="deadline">Clôture du vote <strong>${closesLabel(p)}</strong> · rejoignez la guilde pour voter</p>`;
    } else {
      const res = outcome(p);
      footer = `<span class="result ${res === 'Adoptée' ? 'yes' : 'no'}">${res}</span><p class="deadline">Vote clôturé le ${d(p.date_limite_vote, true)}${mine ? ` · vous avez voté ${mine.reponse_vote}` : ''}</p>`;
    }
    return `<article class="proposal" aria-labelledby="t-${p.id}">
      <img class="art" src="${art(q.type)}" alt="" loading="lazy">
      <div class="body">
        <p class="qline"><img src="${art(q.type)}" alt="">${esc(q.type)} · quête ${esc(q.statut.toLowerCase())}, ${period}${open && member && !mine ? '<span class="flag">À voter</span>' : ''}</p>
        <h3 id="t-${p.id}">${esc(q.titre)}</h3>
        <p class="qdesc">${esc(q.description)}</p>
        ${voteBar(p)}
        <div class="pfoot">${footer}</div>
        <details class="voters">
          <summary>Proposée le ${d(p.date_proposition)} · ${votes.length ? `voir ${plural(votes.length, 'vote', 'votes')}` : "aucun vote pour l'instant"}</summary>
          ${votes.length ? `<ul>${votes.map((v) => `<li><span class="avatar sm" aria-hidden="true">${ini(v.user)}</span><span class="nm">${esc(who(v.user))}</span><span class="ans">${v.reponse_vote}</span><span>${d(v.date_vote)}</span></li>`).join('')}</ul>` : ''}
        </details>
      </div>
    </article>`;
  }

  // ---------- views ----------
  // what a non-member can do with a guild, given that a member belongs to one guild only
  function joinAction(g, big) {
    const home = myGuild(), cls = big ? 'btn primary' : 'btn';
    if (isFull(g.id)) return `<span class="pill full">${big ? 'Guilde complète' : 'Complète'}</span>`;
    if (!home) return `<button class="${cls}" type="button" data-join="${g.id}">${big ? 'Rejoindre la guilde' : 'Rejoindre'}</button>`;
    if (iFounded(home)) return big ? `<span class="pill" title="Le fondateur reste dans sa guilde">Vous avez fondé ${esc(home.nom)}</span>` : '';
    return `<button class="${big ? 'btn' : 'btn'}" type="button" data-switch="${g.id}">${big ? 'Changer pour cette guilde' : 'Changer'}</button>`;
  }

  function guildView(g) {
    const member = isMember(ME_ID, g.id), founder = g.createur === ME_ID, mem = membersOf(g.id).sort((a, b) => a.date_adhesion.localeCompare(b.date_adhesion));
    const props = PROPOSALS.filter((p) => p.guild === g.id);
    const open = props.filter(isOpen).sort((a, b) => a.date_limite_vote.localeCompare(b.date_limite_vote));
    const closed = props.filter((p) => !isOpen(p)).sort((a, b) => b.date_limite_vote.localeCompare(a.date_limite_vote));
    const wait = awaiting(g.id), adopted = closed.filter((p) => outcome(p) === 'Adoptée');
    const tab = state.tab[g.id] || 'open', list = tab === 'open' ? open : closed;
    let finding;
    const home = myGuild();
    if (!member) finding = `<strong>${plural(open.length, 'proposition est', 'propositions sont')} en vote.</strong> ${home ? `Vous êtes membre de ${esc(home.nom)} : seuls les membres de ${esc(g.nom)} votent ici.` : 'Rejoignez la guilde pour voter et proposer des quêtes.'}`;
    else if (wait.length) finding = `<strong>${plural(wait.length, 'proposition attend', 'propositions attendent')} votre vote</strong>, la première se ferme ${closesLabel(wait.sort((a, b) => a.date_limite_vote.localeCompare(b.date_limite_vote))[0])}.`;
    else finding = open.length ? `<strong>Vous avez voté sur les ${plural(open.length, 'proposition', 'propositions')} en cours.</strong>` : '<strong>Aucun vote en cours.</strong> Proposez une quête à la guilde.';
    const openOpenVotes = open.length;
    return `
    <div class="title-row">
      <div class="head"><img class="emblem" src="${emblemOf(g.id)}" alt="">
        <div>${kicker('guilde')}<h1>${esc(g.nom)}</h1><p class="about">${esc(g.description)}</p><p class="sub">${finding}</p></div></div>
      <div class="actions">${member
        ? `<button class="btn primary" type="button" data-action="propose" data-guild="${g.id}">Proposer une quête</button>`
        : joinAction(g, true)}</div>
    </div>
    <div class="split">
      <section class="stack" aria-labelledby="h-props">
        <h2 id="h-props" class="sr">Propositions de quêtes</h2>
        <div class="tabs" role="tablist">
          <a role="tab" tabindex="0" data-gtab="${g.id}:open" aria-selected="${tab === 'open'}">En vote <span class="n">${open.length}</span></a>
          <a role="tab" tabindex="0" data-gtab="${g.id}:closed" aria-selected="${tab === 'closed'}">Votes clôturés <span class="n">${closed.length}</span></a>
        </div>
        ${list.map(proposalCard).join('') || `<div class="panel empty-state"><p><strong>${tab === 'open' ? 'Aucune proposition en vote.' : 'Aucun vote clôturé pour l\'instant.'}</strong></p>${member && tab === 'open' ? `<button class="btn" type="button" data-action="propose" data-guild="${g.id}">Proposer une quête</button>` : ''}</div>`}
      </section>
      <aside class="rail">
        <section aria-labelledby="h-mem"><h2 id="h-mem">Membres</h2>
          <div class="panel" style="padding:20px 20px 16px">
          <div class="cap"><span><b>${mem.length} / ${MAX_MEMBERS} membres</b> · fondée ${founder ? 'par vous' : 'par ' + esc(user(g.createur).pseudo)} le ${d(g.date_creation, true)}</span><div class="capbar"><i style="width:${(mem.length / MAX_MEMBERS) * 100}%"></i></div></div>
          <div class="rows">${mem.map((a) => {
            const done = open.filter((p) => VOTES.some((v) => v.user === a.user && v.proposal === p.id)).length;
            return `<div class="row${a.user === ME_ID ? ' me' : ''}"><span class="avatar sm" aria-hidden="true">${ini(a.user)}</span>
              <span class="who"><strong>${esc(user(a.user).pseudo)}${a.user === ME_ID ? ' (vous)' : ''}</strong><span>${a.user === g.createur ? 'A créé la guilde · ' : ''}membre depuis le ${d(a.date_adhesion, true)}</span></span>
              ${openOpenVotes ? `<span class="num" title="Votes exprimés sur les propositions en cours">${done}/${openOpenVotes} <small>votes</small></span>` : ''}</div>`;
          }).join('')}</div>
          ${member ? `<button class="btn foot-btn" type="button" data-soon="leave-guild">Quitter la guilde</button>${founder ? '<button class="btn danger foot-btn" type="button" data-soon="delete-guild">Supprimer la guilde</button>' : ''}` : ''}</div>
        </section>
        <section aria-labelledby="h-adopt"><h2 id="h-adopt">Quêtes adoptées · ${adopted.length}</h2>
          <div class="panel" style="padding:8px 20px 12px"><div class="rows">${adopted.map((p) => { const q = quest(p.quest); return `<div class="row adopted"><img src="${art(q.type)}" alt=""><span class="who"><strong>${esc(q.titre)}</strong><span>${esc(q.type)} · ${esc(q.statut.toLowerCase())} · jusqu'au ${d(q.date_fin)}</span></span></div>`; }).join('') || '<div class="row"><span class="who"><span>Aucune quête adoptée pour l\'instant.</span></span></div>'}</div></div>
        </section>
      </aside>
    </div>${foot}`;
  }

  function guildsView() {
    const mine = myGuilds(), home = myGuild();
    const waitAll = home ? awaiting(home.id).length : 0;
    const list = state.guildsTab === 'mine' ? mine : state.guildsTab === 'other' ? GUILDS.filter((g) => !isMember(ME_ID, g.id)) : GUILDS;
    const tab = (id, label, k) => `<a role="tab" tabindex="0" data-gltab="${id}" aria-selected="${state.guildsTab === id}">${label} <span class="n">${k}</span></a>`;
    return `
    <div class="title-row"><div>${kicker('guildes')}<h1>Guildes</h1><p class="about">Une seule guilde par membre, dix membres au plus.</p>
      <p class="sub">${home ? `Vous êtes membre de <a class="glink" href="#${home.id}"><strong>${esc(home.nom)}</strong></a>. ${waitAll ? `<strong>${plural(waitAll, 'vote vous attend', 'votes vous attendent')}.</strong>` : 'Aucun vote ne vous attend.'}` : "<strong>Vous n'avez pas encore de guilde.</strong> Rejoignez-en une ou créez la vôtre."}</p></div>
      <div class="actions"><button class="btn primary" type="button" data-action="new-guild">Créer une guilde</button></div></div>
    <div class="tabs" role="tablist">${tab('all', 'Toutes', GUILDS.length)}${tab('mine', 'Ma guilde', mine.length)}${tab('other', 'À découvrir', GUILDS.length - mine.length)}</div>
    <div class="sheet"><div class="table-wrap"><table class="respond">
      <thead><tr><th>Guilde</th><th>Fondée par</th><th>Création</th><th class="n">Membres</th><th class="n">En vote</th><th class="n"><span class="sr">Action</span></th></tr></thead>
      <tbody>${list.map((g) => {
        const m = isMember(ME_ID, g.id), w = awaiting(g.id).length;
        return `<tr>
          <td class="id"><span class="gcell"><img src="${emblemOf(g.id)}" alt=""><span><a class="glink" href="#${g.id}"><strong>${esc(g.nom)}</strong></a><span class="desc">${esc(g.description)}</span></span></span></td>
          <td class="hide-sm">${g.createur === ME_ID ? 'vous' : esc(user(g.createur).pseudo)}</td>
          <td class="hide-sm">${d(g.date_creation, true)}</td>
          <td class="n hide-sm">${membersOf(g.id).length} / ${MAX_MEMBERS}</td>
          <td class="n second">${w ? `<span class="pill lilac">${w} à voter</span> ` : ''}${openOf(g.id).length} en vote</td>
          <td class="end"><span class="row-actions">${m ? `<a class="btn" href="#${g.id}">Ouvrir</a>` : joinAction(g, false) || `<a class="btn" href="#${g.id}">Voir</a>`}</span></td></tr>`;
      }).join('') || '<tr><td colspan="6"><div class="empty">Vous n\'avez pas encore de guilde.</div></td></tr>'}</tbody></table></div></div>${foot}`;
  }

  function questsView() {
    const tabs = ['all', 'À venir', 'En cours', 'Terminée'];
    const list = QUESTS.filter((q) => state.questsTab === 'all' || q.statut === state.questsTab).sort((a, b) => a.date_debut.localeCompare(b.date_debut));
    const tab = (id) => `<a role="tab" tabindex="0" data-qtab="${id}" aria-selected="${state.questsTab === id}">${id === 'all' ? 'Toutes' : id === 'Terminée' ? 'Terminées' : id} <span class="n">${QUESTS.filter((q) => id === 'all' || q.statut === id).length}</span></a>`;
    return `
    <div class="title-row"><div>${kicker('catalogue')}<h1>Quêtes</h1><p class="about">Chaque quête crédite une compétence principale.</p>
      <p class="sub"><strong>${QUESTS.filter((q) => q.statut === 'À venir').length} quêtes à venir.</strong> Une quête rejoint une guilde quand ses membres adoptent la proposition par vote.</p></div></div>
    <div class="tabs" role="tablist">${tabs.map(tab).join('')}</div>
    <div class="sheet"><div class="table-wrap"><table class="respond">
      <thead><tr><th>Quête</th><th>Type</th><th>Période</th><th>Statut</th><th>Propositions</th><th class="n"><span class="sr">Action</span></th></tr></thead>
      <tbody>${list.map((q) => {
        const ps = PROPOSALS.filter((p) => p.quest === q.id);
        return `<tr>
          <td class="id"><span class="qt">${esc(q.titre)}</span><span class="desc">${esc(q.description)}</span></td>
          <td class="hide-sm"><span class="skill"><img src="${art(q.type)}" alt="">${esc(q.type)}</span></td>
          <td class="second" style="white-space:nowrap">${q.date_debut === q.date_fin ? d(q.date_debut, true) : `${d(q.date_debut)} → ${d(q.date_fin, true)}`}</td>
          <td class="hide-sm">${esc(q.statut)}</td>
          <td class="hide-sm"><span class="chips">${ps.map((p) => `<a class="chip" href="#${p.guild}">${esc(guild(p.guild).nom)} · ${isOpen(p) ? 'en vote' : outcome(p).toLowerCase()}</a>`).join('')}</span></td>
          <td class="end"><span class="row-actions">${q.statut !== 'Terminée' && myGuild() ? `<button class="btn" type="button" data-action="propose" data-quest="${q.id}" aria-label="Proposer « ${esc(q.titre)} » à ${esc(myGuild().nom)}">Proposer</button>` : ''}</span></td></tr>`;
      }).join('')}</tbody></table></div></div>${foot}`;
  }

  function accountView() {
    const me = user(ME_ID), myVotes = VOTES.filter((v) => v.user === ME_ID).length;
    return `
    <div class="title-row"><div>${kicker('profil')}<h1>Mon compte</h1><p class="about">yasmine.t</p><p class="sub">Inscrite le ${d(me.date_inscription, true)} · ${myGuild() ? 'membre de ' + esc(myGuild().nom) : 'sans guilde'} · ${plural(myVotes, 'vote exprimé', 'votes exprimés')}.</p></div></div>
    <div class="settings">
      <section class="setting" aria-labelledby="h-pro"><div><h2 id="h-pro">Identifiants</h2><p>Votre pseudo apparaît dans les guildes et à côté de chacun de vos votes.</p></div>
        <form class="form" data-form="profile">
          <div class="field"><label for="f-pseudo">Pseudo</label><input class="input" id="f-pseudo" value="${esc(me.pseudo)}" aria-describedby="f-pseudo-h" required><span class="hint" id="f-pseudo-h">3 à 20 caractères : lettres, chiffres et points.</span></div>
          <div class="field"><label for="f-mail">Adresse e-mail</label><input class="input" id="f-mail" type="email" value="${esc(me.email)}" autocomplete="email" required></div>
          <div class="form-foot"><button class="btn primary" type="submit">Enregistrer</button></div>
        </form></section>
      <section class="setting" aria-labelledby="h-sec"><div><h2 id="h-sec">Mot de passe</h2><p>Il n'est jamais affiché ni envoyé aux autres membres.</p></div>
        <form class="form" data-form="password">
          <div class="field"><label for="f-p1">Nouveau mot de passe</label><input class="input" id="f-p1" type="password" autocomplete="new-password" aria-describedby="f-p-h" minlength="12" required><span class="hint" id="f-p-h">12 caractères au moins.</span></div>
          <div class="field"><label for="f-p2">Confirmer</label><input class="input" id="f-p2" type="password" autocomplete="new-password" required></div>
          <div class="form-foot"><button class="btn" type="submit">Changer le mot de passe</button></div>
        </form></section>
      <section class="setting" aria-labelledby="h-del"><div><h2 id="h-del">Supprimer mon compte</h2><p>${myGuild() ? `Vous quitterez ${esc(myGuild().nom)}.` : ''} ${GUILDS.some((g) => g.createur === ME_ID) ? 'La guilde que vous avez fondée reste à ses membres.' : ''}</p></div>
        <div style="display:flex;align-items:center"><button class="btn danger" type="button" data-action="delete-me">Supprimer mon compte</button></div></section>
    </div>${foot}`;
  }

  // ---------- dialogs ----------
  const dlg = $('#dialog');
  function openDialog(html, onSubmit) {
    dlg.innerHTML = html;
    const form = $('form', dlg);
    form.addEventListener('submit', (e) => { e.preventDefault(); if (onSubmit(new FormData(form), form) !== false) dlg.close(); });
    $$('[data-cancel]', dlg).forEach((b) => b.addEventListener('click', () => dlg.close()));
    dlg.showModal();
    const first = $('input, select, textarea', dlg); if (first) first.focus();
  }
  const confirmDialog = (title, body, label, fn, danger = true) => openDialog(`<form><h2 id="dialog-title">${esc(title)}</h2><p class="lead" style="margin:0">${body}</p>
      <div class="foot"><button class="btn" type="button" data-cancel>Annuler</button><button class="btn primary${danger ? ' destructive' : ''}" type="submit">${esc(label)}</button></div></form>`, () => { fn(); render(); });

  function guildDialog() {
    openDialog(`<form><h2 id="dialog-title">Créer une guilde</h2><p class="lead">Vous en serez le premier membre. Neuf autres pourront la rejoindre.</p>
      <div class="field"><label for="d-nom">Nom</label><input class="input" id="d-nom" name="nom" required maxlength="40"></div>
      <div class="field"><label for="d-desc">Description</label><textarea class="input" id="d-desc" name="description" required maxlength="160" aria-describedby="d-desc-h"></textarea><span class="hint" id="d-desc-h">160 caractères au plus.</span></div>
      <div class="field"><label for="d-skill">Compétence</label><select class="input" id="d-skill" name="competence" required aria-describedby="d-skill-h"><option value="" selected disabled>Choisir une compétence</option>${Object.keys(ART).map((k) => `<option value="${esc(k)}">${esc(k)}</option>`).join('')}</select><span class="hint" id="d-skill-h">La compétence principale que la guilde travaille ensemble.</span></div>
      <div class="foot"><button class="btn" type="button" data-cancel>Annuler</button><button class="btn primary" type="submit">Créer la guilde</button></div></form>`,
    (fd) => {
      // pour le moment le formulaire ne crée rien : il se ferme simplement (à brancher sur le contrôleur PHP)
      toast('Formulaire envoyé : la création de guilde n\'est pas encore branchée');
    });
  }

  function proposeDialog(gid, qid) {
    const gs = myGuilds(); gid = gs[0]?.id; if (!gid) return;
    const options = (g) => QUESTS.filter((q) => q.statut !== 'Terminée').map((q) => {
      const busy = PROPOSALS.some((p) => p.guild === g && p.quest === q.id && (isOpen(p) || outcome(p) === 'Adoptée'));
      return `<option value="${q.id}" ${busy ? 'disabled' : ''} ${q.id === qid ? 'selected' : ''}>${esc(q.titre)}${busy ? ' (déjà proposée)' : ''}</option>`;
    }).join('');
    openDialog(`<form><h2 id="dialog-title">Proposer une quête</h2><p class="lead">Les membres votent jusqu'à la date limite ; la quête est adoptée si les votes « pour » l'emportent.</p>
      <input type="hidden" id="d-g" name="guild" value="${gid}"><p class="lead" style="margin-top:-8px">Pour la guilde <strong style="color:#fff">${esc(guild(gid).nom)}</strong>.</p>
      <div class="field"><label for="d-q">Quête</label><select class="input" id="d-q" name="quest" required>${options(gid)}</select></div>
      <div class="field"><label for="d-lim">Fin du vote</label><input class="input" id="d-lim" name="limite" type="date" required min="${addDays(TODAY, 1)}" value="${addDays(TODAY, 3)}" aria-describedby="d-lim-h"><span class="hint" id="d-lim-h"></span></div>
      <div class="foot"><button class="btn" type="button" data-cancel>Annuler</button><button class="btn primary" type="submit">Soumettre au vote</button></div></form>`,
    (fd, form) => {
      const q = quest(fd.get('quest')), lim = fd.get('limite');
      if (!q) return false;
      GuildeController.proposer(fd.get('guild'), q.id, lim);
      state.tab[fd.get('guild')] = 'open'; toast('Proposition soumise au vote'); location.hash = fd.get('guild'); render();
    });
    // the vote must close before the quest starts: the date field says so and enforces it
    const qs = $('#d-q', dlg), gsel = $('#d-g', dlg), lim = $('#d-lim', dlg), hint = $('#d-lim-h', dlg);
    const sync = () => {
      const q = quest(qs.value);
      if (!q) { hint.textContent = 'Toutes les quêtes ouvertes sont déjà proposées à cette guilde.'; return; }
      const max = q.statut === 'À venir' ? addDays(q.date_debut, -1) : '';
      lim.max = max; if (max && lim.value > max) lim.value = max;
      hint.textContent = max ? `La quête commence le ${d(q.date_debut)} : le vote se termine au plus tard le ${d(max)}.` : 'Quête déjà en cours : la guilde la rejoint dès son adoption.';
    };
    qs.addEventListener('change', sync);
    if (qs.selectedOptions[0]?.disabled) qs.value = [...qs.options].find((o) => !o.disabled)?.value || '';
    sync();
  }


  // ---------- toast ----------
  let tId;
  function toast(msg) { const t = $('#toast'); t.textContent = msg; t.classList.add('show'); clearTimeout(tId); tId = setTimeout(() => t.classList.remove('show'), 2400); }

  // ---------- routing ----------
  const route = () => { const h = location.hash.slice(1); return guild(h) ? h : ['guildes', 'quetes', 'compte'].includes(h) ? h : (guildOf(ME_ID) || 'guildes'); };
  function render() {
    const r = route(), g = guild(r);
    $('#canvas').innerHTML = g ? guildView(g) : r === 'quetes' ? questsView() : r === 'compte' ? accountView() : guildsView();
    $('#my-guilds').innerHTML = (myGuild() ? '' : '<button class="nav-item add" type="button" data-action="new-guild"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>Créer une guilde</button>') + myGuilds().map((x) => { const w = awaiting(x.id).length; return `<a class="nav-item" href="#${x.id}" data-route="${x.id}"><img class="gdot" src="${emblemOf(x.id)}" alt="">${esc(x.nom)}${w ? `<span class="count" aria-label="${w} à voter">${w}</span>` : ''}</a>`; }).join('');
    $$('.nav-item[data-route]').forEach((a) => (a.dataset.route === r ? a.setAttribute('aria-current', 'page') : a.removeAttribute('aria-current')));
    const title = g ? g.nom : { guildes: 'Guildes', quetes: 'Quêtes', compte: 'Mon compte' }[r];
    $('#mobile-title').textContent = title; document.title = `${title} · Guildes`;
    document.dispatchEvent(new CustomEvent('yallaquest:render', { detail: { route: location.hash.slice(1) || 'guildes' } }));
  }

  // ---------- events ----------
  document.addEventListener('click', (e) => {
    const t = e.target.closest('button, a[role="tab"]');
    if (!t) return;
    const ds = t.dataset;
    if (ds.action === 'new-guild') return guildDialog();
    if (ds.action === 'propose') return proposeDialog(ds.guild, ds.quest);
    if (ds.action === 'delete-me') return confirmDialog('Supprimer votre compte ?', 'Vos votes resteront comptés dans les propositions clôturées. Cette action est définitive.', 'Supprimer mon compte', () => toast('Demande de suppression enregistrée'));
    if (ds.vote) {
      const p = PROPOSALS.find((x) => x.id === ds.vote), r = GuildeController.voter(p.id, ds.answer);
      if (!r) return;
      toast(`Vote ${r} : ${ds.answer}`); render();
      $(`[data-vote="${p.id}"][data-answer="${ds.answer}"]`)?.focus(); return;
    }
    if (ds.switch) { const g = guild(ds.switch), home = myGuild(); return confirmDialog(`Quitter ${home.nom} pour ${g.nom} ?`, `Un membre n'appartient qu'à une guilde. Vos votes en cours dans ${esc(home.nom)} seront retirés ; vos votes clôturés restent comptés.`, 'Changer de guilde', () => {
      GuildeController.changerDeGuilde(home.id, g.id); location.hash = g.id; toast(`Bienvenue dans ${g.nom}`);
    }, false); }
    if (ds.join) { const g = guild(ds.join); if (isFull(g.id)) return toast(`${g.nom} est complète (${MAX_MEMBERS} membres)`); if (guildOf(ME_ID)) return toast('Un membre n\'appartient qu\'à une guilde'); GuildeController.rejoindre(g.id); toast(`Bienvenue dans ${g.nom}`); location.hash = g.id; return render(); }
    if (ds.leave) { const g = guild(ds.leave); return confirmDialog(`Quitter ${g.nom} ?`, 'Vos votes sur les propositions en cours seront retirés. Vous pourrez rejoindre la guilde à nouveau.', 'Quitter la guilde', () => {
      GuildeController.quitter(g.id); toast(`Vous avez quitté ${g.nom}`);
    }); }
    if (ds.gtab) { const [g, k] = ds.gtab.split(':'); state.tab[g] = k; return render(); }
    if (ds.gltab) { state.guildsTab = ds.gltab; return render(); }
    if (ds.qtab) { state.questsTab = ds.qtab; return render(); }
  });
  document.addEventListener('keydown', (e) => { if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('[role="tab"]')) { e.preventDefault(); e.target.click(); } });
  document.addEventListener('submit', (e) => { const f = e.target.dataset.form; if (f) { e.preventDefault(); toast(f === 'profile' ? 'Identifiants enregistrés' : 'Mot de passe modifié'); } });

  const sb = $('#sidebar'), tg = $('.menu-toggle');
  const menu = (open) => { sb.classList.toggle('open', open); tg.setAttribute('aria-expanded', open); };
  tg.addEventListener('click', () => menu(true));
  $('.close-menu').addEventListener('click', () => menu(false));
  sb.addEventListener('click', (e) => { if (e.target.closest('.nav-item')) menu(false); });
  window.addEventListener('hashchange', () => { render(); $('#canvas').focus({ preventScroll: true }); window.scrollTo(0, 0); });
  render();
})();

